/*{
  "DESCRIPTION": "Gently falling snow flakes drifting down over a dark night sky",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "skyColor", "TYPE": "color", "DEFAULT": [0.02, 0.03, 0.1, 1.0] },
    { "NAME": "snowColor", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 1.0, "MAX": 6.0, "DEFAULT": 3.0 },
    { "NAME": "flakeSize", "TYPE": "float", "MIN": 0.02, "MAX": 0.2, "DEFAULT": 0.08 }
  ]
}*/

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

void main() {
  vec2 uv = isf_FragNormCoord;
  bool isRoofline = RENDERSIZE.y < 2.0;

  vec3 col = skyColor.rgb;

  int layers = int(density);
  for (int i = 0; i < 6; i++) {
    if (i >= layers) break;

    float fi = float(i);
    float layerScale = 4.0 + fi * 3.0;
    float fallSpeed = (0.15 + fi * 0.08) * speed;
    float wobbleAmt = 0.15 / (1.0 + fi * 0.4);

    vec2 guv;
    if (isRoofline) {
      // drive the falling motion along x instead of y on a 1px-tall roofline
      float t = uv.x * layerScale + TIME * fallSpeed * 4.0;
      float wobble = sin(TIME * 0.6 + fi * 10.0) * wobbleAmt;
      guv = vec2(t, uv.y * layerScale + wobble + fi * 17.0);
    } else {
      float fallT = uv.y * layerScale + TIME * fallSpeed * 4.0;
      float wobble = sin(TIME * 0.8 + uv.y * 20.0 + fi * 10.0) * wobbleAmt;
      guv = vec2(uv.x * layerScale + wobble + fi * 13.0, fallT);
    }

    vec2 cell = floor(guv);
    vec2 f = fract(guv) - 0.5;

    vec2 jitter = vec2(hash(cell + fi), hash(cell + fi + 5.0)) - 0.5;
    jitter *= (1.0 - flakeSize * 2.0);

    float d = length(f - jitter);
    float flake = smoothstep(flakeSize, flakeSize * 0.3, d);

    float twinkle = 0.7 + 0.3 * sin(TIME * 2.0 + hash(cell) * 6.2831);
    col = mix(col, snowColor.rgb, flake * twinkle);
  }

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Flickering fire rising from the bottom of the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.8, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.1, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 6.0, "DEFAULT": 2.5 },
    { "NAME": "intensity", "TYPE": "float", "MIN": 0.0, "MAX": 2.0, "DEFAULT": 1.0 }
  ]
}*/

float hash1(float n) {
  return fract(sin(n) * 43758.5453);
}

float noise1(float x) {
  float i = floor(x);
  float f = fract(x);
  float a = hash1(i);
  float b = hash1(i + 1.0);
  return mix(a, b, smoothstep(0.0, 1.0, f));
}

void main() {
  vec2 uv = isf_FragNormCoord;
  bool flat1D = RENDERSIZE.y < 2.0;

  float rise = TIME * speed * 0.6;

  float h;
  if (flat1D) {
    h = uv.x;
  } else {
    h = uv.y;
  }

  float n1 = noise1(uv.x * scale * 6.0 + rise * 4.0 + h * 2.0);
  float n2 = noise1(uv.x * scale * 12.0 - rise * 6.0 + h * 5.0 + 17.0);
  float flick = hash1(floor(TIME * 12.0 * speed) + uv.x * 3.0);

  float wave = mix(n1, n2, 0.4) + flick * 0.15;

  float travel = fract(h - rise * 0.5 - wave * 0.3);

  float flame = 1.0 - travel;
  flame = pow(clamp(flame, 0.0, 1.0), 2.0 + scale * 0.3);
  flame *= (0.7 + 0.3 * wave);
  flame *= intensity;

  float heat = clamp(flame, 0.0, 1.0);
  vec3 col = mix(colorB.rgb * 0.4, colorA.rgb, heat);
  col = mix(vec3(0.0), col, smoothstep(0.0, 0.15, heat));

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Diagonal red and white candy cane stripes scrolling across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 1.0, "MAX": 12.0, "DEFAULT": 5.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.7 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  float diag;
  if (RENDERSIZE.y < 2.0) {
    // flat roofline: fake diagonal motion using x alone
    diag = uv.x * scale - TIME * speed * 0.6;
  } else {
    diag = (uv.x + uv.y) * scale - TIME * speed * 0.6;
  }

  float stripe = fract(diag);
  float edge = mix(0.02, 0.45, sharpness);
  float band = smoothstep(0.5 - edge, 0.5 + edge, stripe);

  vec3 col = mix(colorA.rgb, colorB.rgb, band);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A smooth glowing wash that fades gently between the palette colours",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "softness", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 1.0 }
  ]
}*/
void main() {
  float t = TIME * speed * 0.15;

  float cyclePos = fract(t);
  float seg = cyclePos * 3.0;

  vec3 c0;
  vec3 c1;
  float localT;

  if (seg < 1.0) {
    c0 = colorA.rgb;
    c1 = colorB.rgb;
    localT = seg;
  } else if (seg < 2.0) {
    c0 = colorB.rgb;
    c1 = colorC.rgb;
    localT = seg - 1.0;
  } else {
    c0 = colorC.rgb;
    c1 = colorA.rgb;
    localT = seg - 2.0;
  }

  float edge = clamp(0.5 / max(softness, 0.1), 0.0, 0.5);
  float mixAmt = smoothstep(0.5 - edge, 0.5 + edge, localT);

  vec3 col = mix(c0, c1, mixAmt);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Twinkling stars scattered across the display in two colours",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.85, 0.3, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 4.0, "MAX": 40.0, "DEFAULT": 16.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.05, "MAX": 1.0, "DEFAULT": 0.35 }
  ]
}*/

float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.x, p.y, p.x) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

void main() {
  vec2 uv = isf_FragNormCoord;

  // Keep the field usable even on a 1-pixel-tall roofline: give it a
  // synthetic vertical extent so we still get a scatter of stars.
  vec2 gridUV = uv;
  if (RENDERSIZE.y < 2.0) {
    gridUV.y = fract(uv.x * 3.17);
  }

  vec2 cellSize = vec2(1.0 / density);
  vec2 cellID = floor(gridUV / cellSize);

  vec3 col = vec3(0.0);

  // check a small neighborhood so star glow can spread past cell edges
  for (int dx = -1; dx <= 1; dx++) {
    for (int dy = -1; dy <= 1; dy++) {
      vec2 neighbor = cellID + vec2(float(dx), float(dy));
      float r = hash(neighbor);

      // random position of star within its cell
      vec2 jitter = vec2(hash(neighbor + 0.11), hash(neighbor + 0.37));
      vec2 starPos = (neighbor + jitter) * cellSize;

      vec2 diff = gridUV - starPos;
      // correct for aspect so stars stay round-ish
      diff.x *= RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
      float d = length(diff);

      // twinkle: each star has its own phase and rate
      float phase = r * 6.2831853;
      float rate = 0.6 + r * 1.4;
      float twinkle = 0.5 + 0.5 * sin(TIME * speed * rate + phase);
      twinkle = pow(twinkle, 2.0);

      float radius = cellSize.x * mix(0.15, 0.45, sharpness) * (0.5 + 0.5 * r);
      float star = smoothstep(radius, 0.0, d) * twinkle;

      // colour choice per star, biased by hash
      vec3 starColor = mix(colorA.rgb, colorB.rgb, step(0.5, hash(neighbor + 0.73)));

      col += starColor * star;
    }
  }

  col = clamp(col, 0.0, 1.0);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A chase of colored dots runs continuously along the roofline",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "count", "TYPE": "float", "MIN": 2.0, "MAX": 16.0, "DEFAULT": 8.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.05, "MAX": 0.5, "DEFAULT": 0.2 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  // Use x along the roofline always; if buffer is tall (not a roofline),
  // still favor x-driven motion per the instructions.
  float pos = uv.x;

  // moving coordinate along the chase, wraps seamlessly
  float t = fract(pos * count - TIME * speed);

  // distance to nearest dot center in wrapped space
  float d = min(t, 1.0 - t);

  // sharp-edged dot with soft falloff for anti-alias
  float dot = smoothstep(sharpness, sharpness * 0.5, d);

  // cycle through three colors based on which light index we're at
  float idx = floor(pos * count - TIME * speed);
  float cyc = mod(idx, 3.0);

  vec3 col = colorA.rgb;
  if (cyc > 0.5 && cyc < 1.5) {
    col = colorB.rgb;
  } else if (cyc >= 1.5) {
    col = colorC.rgb;
  }

  // dim background so unlit gaps read as "off" but not pure black harshness
  vec3 background = vec3(0.02, 0.02, 0.03);

  vec3 finalColor = mix(background, col, dot);

  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "Swirling plasma blend of colours across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 6.0, "DEFAULT": 2.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;

  float t = TIME * speed;

  vec2 p;
  if (isLine) {
    p = vec2(uv.x * scale, t * 0.3);
  } else {
    p = uv * scale;
  }

  float x = p.x;
  float y = isLine ? p.y : p.y;

  float v = 0.0;
  v += sin(x * 3.0 + t);
  v += sin((y * 3.0 + t * 0.7) * 1.3);
  v += sin((x + y) * 2.0 + t * 1.1);

  float cx = x + 0.5 * sin(t * 0.3);
  float cy = y + 0.5 * cos(t * 0.25);
  v += sin(sqrt(cx * cx + cy * cy + 1.0) * 4.0 - t * 1.5);

  v *= 0.25;
  v = v * 0.5 + 0.5;

  vec3 col;
  float third = 1.0 / 3.0;
  if (v < third) {
    col = mix(colorA.rgb, colorB.rgb, v / third);
  } else if (v < 2.0 * third) {
    col = mix(colorB.rgb, colorC.rgb, (v - third) / third);
  } else {
    col = mix(colorC.rgb, colorA.rgb, (v - 2.0 * third) / third);
  }

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A saturated rainbow band sweeps sideways across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 6.0, "DEFAULT": 2.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.6 }
  ]
}*/
vec3 rainbow(float t) {
  float h = fract(t);
  float r = clamp(abs(h * 6.0 - 3.0) - 1.0, 0.0, 1.0);
  float g = clamp(2.0 - abs(h * 6.0 - 2.0), 0.0, 1.0);
  float b = clamp(2.0 - abs(h * 6.0 - 4.0), 0.0, 1.0);
  return vec3(r, g, b);
}

void main() {
  vec2 uv = isf_FragNormCoord;
  float pos = (RENDERSIZE.y < 2.0) ? uv.x : uv.x;

  float hue = pos * scale - TIME * speed * 0.3;
  vec3 col = rainbow(hue);

  float boost = mix(1.0, 1.8, sharpness);
  col = clamp((col - 0.5) * boost + 0.5, 0.0, 1.0);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Everything pulses in bright bands to a steady beat",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 0.8, 0.2, 1.0] },
    { "NAME": "bpm", "TYPE": "float", "MIN": 40.0, "MAX": 200.0, "DEFAULT": 120.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 1.0, "MAX": 16.0, "DEFAULT": 6.0 },
    { "NAME": "bands", "TYPE": "long", "MIN": 1.0, "MAX": 8.0, "DEFAULT": 3.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  float beatsPerSec = bpm / 60.0;
  float phase = fract(TIME * beatsPerSec);

  // Sharp pulse: near 1.0 right on the beat, decaying quickly
  float pulse = pow(1.0 - phase, sharpness);
  pulse = clamp(pulse, 0.0, 1.0);

  // Split canvas into bands so it reads as a pattern even on thin strips
  float n = float(bands);
  float coord = (RENDERSIZE.y < 2.0) ? uv.x : uv.x;
  float bandIndex = floor(coord * n);
  float bandFrac = fract(bandIndex * 0.5);
  float colorMix = step(0.5, bandFrac);

  vec3 baseColor = mix(colorA.rgb, colorB.rgb, colorMix);

  // Pulse brightness: dim base glow plus bright flash on the beat
  float brightness = mix(0.25, 1.0, pulse);

  vec3 finalColor = baseColor * brightness;

  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "A waving American-style flag of red, white and blue stripes with a blue canton",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.8, 0.0, 0.1, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.1, 0.5, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "waveAmount", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.4 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isRoofline = RENDERSIZE.y < 2.0;

  // wave phase travels along x, displaces the "other" axis to fake cloth motion
  float t = TIME * speed;

  if (isRoofline) {
    // single line of lights: fold the flag into x alone.
    // sweep through stripes left to right, with a horizontal ripple to read as waving.
    float wave = sin(uv.x * 10.0 + t * 2.0) * waveAmount * 0.05;
    float pos = fract(uv.x + wave);

    // first ~35% of the strip is the canton (blue), rest is stripes
    if (pos < 0.35) {
      gl_FragColor = vec4(colorC.rgb, 1.0);
    } else {
      float stripePos = (pos - 0.35) / 0.65;
      float stripeIndex = floor(stripePos * 7.0);
      float band = mod(stripeIndex, 2.0);
      vec3 col = mix(colorA.rgb, colorB.rgb, band);
      gl_FragColor = vec4(col, 1.0);
    }
    return;
  }

  // full 2D flag
  float wave = sin(uv.x * 6.0 + t * 2.0) * waveAmount * 0.06;
  float wave2 = sin(uv.x * 3.0 + t * 1.3) * waveAmount * 0.03;
  float y = uv.y + wave + wave2;

  float cantonWidth = 0.4;
  float cantonHeight = 0.55;

  vec3 col;

  if (uv.x < cantonWidth && y > (1.0 - cantonHeight)) {
    // canton: blue field, simple star sparkle grid
    vec2 starUV = vec2(uv.x / cantonWidth, (y - (1.0 - cantonHeight)) / cantonHeight);
    vec2 grid = fract(starUV * vec2(6.0, 5.0)) - 0.5;
    float d = length(grid);
    float star = smoothstep(0.14, 0.06, d);
    col = mix(colorC.rgb, colorB.rgb, star * 0.9);
  } else {
    // stripes: 13 stripes across full height
    float stripeIndex = floor(y * 13.0);
    float band = mod(stripeIndex, 2.0);
    col = mix(colorA.rgb, colorB.rgb, band);
  }

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Spooky green fog drifting slowly across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.02, 0.15, 0.05, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.2, 0.9, 0.3, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 0.6 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 6.0, "DEFAULT": 2.0 },
    { "NAME": "thickness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.5 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isFlat = RENDERSIZE.y < 2.0;

  float t = TIME * speed * 0.15;

  float x = isFlat ? uv.x : uv.x;
  float y = isFlat ? uv.x * 0.35 : uv.y;

  float wave1 = sin((x * scale + t) * 6.28318) * 0.5 + 0.5;
  float wave2 = sin((x * scale * 1.7 - t * 1.3 + y * 2.0) * 6.28318) * 0.5 + 0.5;
  float wave3 = sin((x * scale * 0.6 + t * 0.6 - y * 1.2) * 6.28318) * 0.5 + 0.5;

  float fog = (wave1 * 0.5 + wave2 * 0.3 + wave3 * 0.2);

  float edge = mix(0.15, 0.85, thickness);
  fog = smoothstep(edge - 0.25, edge + 0.25, fog);

  float pulse = sin(TIME * speed * 0.3) * 0.05 + 0.95;
  fog *= pulse;

  vec3 col = mix(colorA.rgb, colorB.rgb, fog);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Spinning tunnel of concentric rings flying toward the viewer",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "rings", "TYPE": "float", "MIN": 2.0, "MAX": 16.0, "DEFAULT": 8.0 },
    { "NAME": "twist", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 }
  ]
}*/
void main() {
  vec2 uv;
  bool isFlat = RENDERSIZE.y < 2.0;

  if (isFlat) {
    // one-pixel-tall model: fake the tunnel by sliding along x instead of radius
    float x = isf_FragNormCoord.x;
    float t = TIME * speed;

    float radial = fract(x * rings - t * 1.5);
    float ring = smoothstep(0.0, 0.12, radial) - smoothstep(0.38, 0.5, radial);

    float spin = sin(x * 6.2831 * twist + t * 3.0);
    float mixer = 0.5 + 0.5 * spin;

    vec3 base = mix(colorA.rgb, colorB.rgb, mixer);
    vec3 col = mix(base, colorC.rgb, ring);

    // pulse brightness along x to read as depth motion
    float pulse = 0.6 + 0.4 * sin(x * 6.2831 - t * 4.0);
    col *= pulse;

    gl_FragColor = vec4(col, 1.0);
    return;
  }

  // normalize coords to centered -1..1, correct aspect
  vec2 res = RENDERSIZE;
  uv = (isf_FragNormCoord - 0.5) * 2.0;
